css:
body { font-family: system-ui, sans-serif; padding: 1rem; background: #fff8ef; }
.dishes { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 1rem; }
figure { margin: 0; }

/* Your CSS below:
   1. No image may be wider than its box (max-width + height: auto)
   2. .dish img: full width, 4 / 3 shape, cropped not squashed (object-fit) */
img { max-width: 100%; height: auto; display: block; }
.dish img { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; }

js:
